public static void Main(Args _args)
{
    FTDBookTable bookTable = FTDWorkingWithGenerics::genericFindRecId(tableNum(FTDBookTable), 5637146076);

    Info(bookTable.Id);

    FTDAuthorTable author = FTDWorkingWithGenerics::genericFindByField(tableNum(FTDAuthorTable), fieldNum(FTDAuthorTable, Id), 'A001');

    Info(author.FirstName +' '+ author.LastName);
}
